static void *actor_main(void *arg) {
    actor_t *self = arg;
    for (;;) {
        msg_t *msg = mailbox_pop(&self->mbox);   /* waits on mutex + condvar */
        if (!msg) break;                         /* NULL = shutdown */
        self->handle(self, msg);                 /* state touched only here */
        msg_free(msg);
    }
    return NULL;
}
